CREATE TABLE runtime_provider_trust_admissions(admission_id TEXT PRIMARY KEY,version INTEGER NOT NULL CHECK(version=1),admission_digest TEXT NOT NULL UNIQUE,tenant_id TEXT NOT NULL,company_id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,oks_decision_id TEXT NOT NULL,oks_binding_id TEXT NOT NULL,oks_consumption_id TEXT NOT NULL,manifest_id TEXT NOT NULL,projection_digest TEXT NOT NULL,effective_context_json TEXT NOT NULL,provider_trust_eligibility_id TEXT NOT NULL,evaluation_id TEXT NOT NULL,evaluation_digest TEXT NOT NULL,policy_ids_json TEXT NOT NULL,policy_versions_json TEXT NOT NULL,policy_digest TEXT NOT NULL,attestation_set_digest TEXT NOT NULL,runtime_binding_id TEXT NOT NULL,runtime_binding_digest TEXT NOT NULL,provider TEXT NOT NULL,provider_account_id TEXT NOT NULL,provider_deployment_id TEXT NOT NULL,adapter_identity TEXT NOT NULL,selected_model TEXT NOT NULL,credential_reference TEXT NOT NULL,issued_at TEXT NOT NULL,expires_at TEXT NOT NULL,reservation_id TEXT NOT NULL UNIQUE,invocation_consumer TEXT NOT NULL CHECK(invocation_consumer='COGNITIVE_PROVIDER_INVOCATION'),correlation_id TEXT NOT NULL,causal_references_json TEXT NOT NULL,transport_executed INTEGER NOT NULL CHECK(transport_executed=0));
CREATE TABLE runtime_provider_trust_reservations(reservation_id TEXT PRIMARY KEY,admission_id TEXT NOT NULL UNIQUE REFERENCES runtime_provider_trust_admissions(admission_id),invocation_consumer TEXT NOT NULL,consumed_at TEXT NOT NULL);
CREATE TABLE runtime_provider_trust_denials(denial_id TEXT PRIMARY KEY,failure_code TEXT NOT NULL,correlation_id TEXT NOT NULL,recorded_at TEXT NOT NULL,causal_references_json TEXT NOT NULL);
CREATE TABLE runtime_provider_trust_audit_events(event_id TEXT PRIMARY KEY,event_kind TEXT NOT NULL,subject_id TEXT NOT NULL,outcome TEXT NOT NULL,failure_code TEXT,correlation_id TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE TRIGGER runtime_provider_trust_admission_immutable BEFORE UPDATE ON runtime_provider_trust_admissions BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_ADMISSION_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_admission_no_delete BEFORE DELETE ON runtime_provider_trust_admissions BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_ADMISSION_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_reservation_immutable BEFORE UPDATE ON runtime_provider_trust_reservations BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_RESERVATION_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_reservation_no_delete BEFORE DELETE ON runtime_provider_trust_reservations BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_RESERVATION_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_denial_immutable BEFORE UPDATE ON runtime_provider_trust_denials BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_DENIAL_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_denial_no_delete BEFORE DELETE ON runtime_provider_trust_denials BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_DENIAL_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_audit_immutable BEFORE UPDATE ON runtime_provider_trust_audit_events BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_AUDIT_IMMUTABLE');END;
CREATE TRIGGER runtime_provider_trust_audit_no_delete BEFORE DELETE ON runtime_provider_trust_audit_events BEGIN SELECT RAISE(ABORT,'RUNTIME_PROVIDER_TRUST_AUDIT_IMMUTABLE');END;
